 let node=document.querySelector('[data-sheet-download-status]');if(!node){node=document.createElement('div');node.className='sheet-download-status';node.dataset.sheetDownloadStatus='';node.setAttribute('role','status');node.setAttribute('aria-live','polite');document.body.append(node)}
 node.innerHTML=`<span class="sheet-download-orbit" aria-hidden="true">✦</span><strong>${esc(text)}</strong><small>Tu peux continuer à utiliser Astralis, la page reste ouverte.</small>`;
