 if(person){icon=person.image;label=person.name;kind='person'}
 else if(weapon){icon=weapon.image;label=weapon.name;kind='weapon'}
 else if(artifact){icon=artifact.image;label=artifact.name;kind='artifact'}
 else if(ELEMENT_ICONS.includes(key)){icon=`/assets/genshin/elements/gi-${key}.png`;label=key;kind='element'}
